var max_creeps = 30;

var creeps = [];
var rotations;

var paused = false;

function setup() {
	createCanvas(windowHeight - 100, windowHeight - 100);
	background(20);

	rotations = round(random(2,12))

	for(var i = 0; i < 3; i++){
		creeps[i] = new Creep();
	}

	colorMode(RGB, 255);
	fill(25);
	noStroke();
	rect(0, 0, width, height);
	noFill();
	stroke(50);
	strokeWeight(3);
	ellipse(width/2, height/2, width*0.805, height*0.805);
}

function draw() {
	if(!paused){
		for(var i = 0; i < creeps.length; i++){
			creeps[i].update();
		}

		if(creeps.length == 0){
			creeps.push(new Creep());
		}

		resetMatrix();
		colorMode(RGB, 255);
		blendMode(BLEND);
		noFill();
		stroke(20);
		strokeWeight(40);
		rect(-10, -10, width+20, height+20, 80);
	}
}

function mouseClicked() {
	var creep = new Creep();
	creep.x = (window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX)))-width/2;
	creep.y = (window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY)))-height/2;
  creeps.push(creep);
}

function keyPressed() {
  if (keyCode == 32) {

    rotations = round(random(2,12))
		creeps = []
		colorMode(RGB, 255);
		fill(25);
		noStroke();
		rect(0, 0, width, height);
		noFill();
		stroke(50);
		strokeWeight(3);
		ellipse(width/2, height/2, width*0.805, height*0.805);
		paused = false;
  }
	if(keyCode == 80){
		paused = !paused;
	}
	if(keyCode == 70){
		var pic = get();
		pic.filter(BLUR);
		pic.filter(POSTERIZE);
		image(pic, 0, 0);
	}
}

class Creep{
	constructor(){
		this.reset();
	}

	update(){
		this.size = noise(frameCount * 0.05, this.seed) * 3 + 0.1;

		colorMode(HSB, 1.0);
		var h = hue(window.color(this.color));
		this.color = color(h+0.0025, 0.5, 0.8)
		colorMode(RGB, 255);

		//this.dir += map(noise(this.seed + frameCount * this.scale), 0, 1, -this.rate, this.rate);
		this.dir = map(noise(this.x * 0.01, this.y * 0.01, this.seed), 0, 1, -TWO_PI, TWO_PI);

		this.x += cos(this.dir)*this.size*0.7;
		this.y += sin(this.dir)*this.size*0.7;
		var pix = get(this.x+width/2, this.y+height/2);
		var col = color(pix[0], pix[1], pix[2]);
		if(brightness(window.color(col)) < 0.5){			
			this.draw();
		}else{
			this.remove();
		}

		if(p5.Vector.dist(createVector(this.x, this.y), createVector(0,0)) > width*0.4) this.remove();

		if(random() < this.branch_rate) this.new();
	}

	draw(){		
		push();
		translate(width/2,height/2)
		noStroke();
		fill(this.color);
		for(var i = 0; i < rotations; i++){			
			rotate(TWO_PI / rotations);
			ellipse(this.x, this.y, this.size, this.size);
			ellipse(-this.x, this.y, this.size, this.size);
		}
		pop();
	}

	reset(){
			colorMode(HSB, 1.0);
			this.color = color(random(), 0.5, 0.8);
			colorMode(RGB, 255);
			this.seed = random(99999);
			var pos = p5.Vector.random2D().mult(random()*width*0.4);
			this.x = pos.x; //random(-width/3,width/3);
		  this.y = pos.y; //random(-height/3,height/3);			
			this.dir = random(TWO_PI);
			this.scale = random(0.01, 0.1);
			this.rate = random(0.01, 0.1);
			this.branch_rate = random(0.01, 0.1);
	}

	remove(){
		var index = creeps.indexOf(this);
		if (index > -1) {
			creeps.splice(index, 1);
		}
	}

	new(){
		if(creeps.length < max_creeps){
			var creep = new Creep();
			creep.x = this.x;
			creep.y = this.y;
			creep.color = this.color;
			creeps.push(creep);
		}
	}
}
